  "response_type": "partial_answer",
  "answer": "This policy states that damaged or missing equipment is reviewed by HR Admin and IT Admin before any payroll or final-pay action, and that the policy itself does not authorize payroll deductions. Operations may provide a prepaid shipping label for equipment returns, but it is not stated as mandatory. Whether Operations must deduct pay automatically is not specified in this policy.",
  "citations": [
    {
      "document_id": "OPS-001",
      "document_title": "Vendor, Travel, and Equipment Operations Policy",
      "section_heading": "Shipping and Return Rules",
      "chunk_id": "7f43621b-e723-47b9-b347-6c633696ca67",
      "citation_text": "Damaged or missing equipment is reviewed by HR Admin and IT Admin before any payroll or final-pay action. This policy does not authorize payroll deductions by itself. Operations may provide a prepaid shipping label."
    }
  ],
  "supported_claims": [
    "The policy does not authorize payroll deductions by itself.",
    "Damaged or missing equipment is reviewed by HR Admin and IT Admin before any payroll or final-pay action.",
    "Operations may provide a prepaid shipping label."
  ],
  "unsupported_claims": [
    "Operations must deduct pay automatically for damaged equipment returns.",
    "A prepaid shipping label is mandatory for equipment returns."
  ],
  "validation_notes": "The policy clarifies review and authorization roles but does not mandate automatic payroll deductions or require prepaid shipping labels."
}
